WITH cleaned AS (SELECT id, customer_id, account_type, balance, YEAR(opened_date) AS opened_date_year, COALESCE(status, 'NONE') AS resolved_status FROM accounts WHERE status IS NOT NULL AND balance IS NOT NULL) SELECT id, balance, opened_date_year, AVG(opened_date_year) OVER (PARTITION BY account_type, customer_id) AS account_type_avg_opened_date_year, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY balance DESC) AS balance_percent_rank, AVG(balance) OVER w_recent AS balance_avg_2 FROM cleaned WINDOW w_recent AS (PARTITION BY customer_id ORDER BY opened_date_year ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW);
